import functools
import time


def ttl_cache(ttl, clock=time.monotonic):
    if ttl <= 0:
        raise ValueError('ttl must be > 0')

    def decorator(func):
        cache = {}

        @functools.wraps(func)
        def wrapper(*args):
            now = clock()
            hit = cache.get(args)
            if hit is not None and now - hit[1] < ttl:
                return hit[0]
            value = func(*args)
            cache[args] = (value, now)
            return value
        return wrapper
    return decorator


# ---------------------------------------------------------------------------
# Test harness (do not change). events: [["call", arg, now], ...]
# Returns what each call returned; the underlying function tags results with a call counter.
# ---------------------------------------------------------------------------
def simulate(ttl, events):
    now = {"t": 0}
    calls = {"n": 0}

    @ttl_cache(ttl, clock=lambda: now["t"])
    def get_secret(name):
        """Pretend this hits AWS Secrets Manager."""
        calls["n"] += 1
        return f"{name}#{calls['n']}"

    out = []
    for _, arg, t in events:
        now["t"] = t
        out.append(get_secret(arg))
    return {"results": out, "backend_calls": calls["n"], "name": get_secret.__name__}
